double h = b - a;
double I1 = 0.5 * h * (f(a) + f(b));
double S = 0.0;
double sum = 0.0;
int it = 1;
double I2 = 0.0;

do {
    I1 = I2;
    sum = 0.0;
    for (int k = 1; k <= it; k++) {
        sum += f(a + (k - 0.5) * h);
    }
    I2 = 0.5 * I1 + sum * h;
    it <<= 1;
    h *= 0.5;
} while (std::abs(I2 - I1) > precision);

S = I2;
return S;
// END_CODE

